<script setup lang="ts">
import {computed,onBeforeUnmount,ref,shallowRef,watch} from 'vue';
import {api} from '../api';import {reviewView,reviewRequestId,type InterimReviewView} from '../utils/interim-review';
import {dispositionLabels} from '../utils/sdk-operations';import {useAuth} from '../composables/auth';
import Button from './ui/Button.vue';import Input from './ui/Input.vue';import Select from './ui/Select.vue';import StatusBadge from './StatusBadge.vue';
const props=defineProps<{groupId:number;revision?:number}>(),emit=defineEmits<{archived:[]}>();const {canOperate}=useAuth();
const value=shallowRef<InterimReviewView|null>(null),loading=ref(false),busy=ref(false),error=ref(''),ack=ref(false),title=ref(''),severity=ref('info'),description=ref('');let epoch=0,disposed=false,timer:ReturnType<typeof setTimeout>|undefined,retryId='';
const latest=computed(()=>value.value?.history[0]),active=computed(()=>latest.value&&!['failed','canceled','completed','timeout','partial'].includes(latest.value.status));
const canArchive=computed(()=>!value.value?.archive&&!latest.value?.error&&latest.value?.status==='completed'&&latest.value.outcome?.disposition==='reportable'&&value.value?.sourceCheck?.state==='checked');
const options=['critical','high','medium','low','info'].map(v=>({value:v,label:v}));
async function load(){const gen=++epoch,id=props.groupId;loading.value=true;error.value='';try{const v=reviewView(await api.interimReview(id),id);if(disposed||gen!==epoch)return;if(!v)throw new Error('复核组的执行、源码或结论绑定不匹配，已拒绝展示。');value.value=v;if(!title.value){title.value=v.input.members[0]!.candidate.title;const s=v.input.members[0]!.candidate.reportedSeverity?.toLowerCase();severity.value=options.some(o=>o.value===s)?s!:'info';}clearTimeout(timer);if(v.history.some(h=>!['failed','canceled','completed','timeout','partial'].includes(h.status)))timer=setTimeout(()=>void load(),4000);}catch(e){if(!disposed&&gen===epoch)error.value=(e as Error).message;}finally{if(!disposed&&gen===epoch)loading.value=false}}
async function retry(){if(!ack.value||busy.value||!canOperate.value)return;const gen=epoch,id=props.groupId;busy.value=true;error.value='';retryId ||= reviewRequestId();try{await api.retryInterimReview(id,retryId);if(disposed||gen!==epoch)return;retryId='';ack.value=false;await load()}catch(e){if(!disposed&&gen===epoch)error.value='重新复核未创建：'+(e as Error).message}finally{busy.value=false}}
async function archive(){const h=latest.value;if(!h?.outcome||!canArchive.value||busy.value||!canOperate.value)return;const id=props.groupId,gen=epoch;busy.value=true;error.value='';try{await api.archiveInterimReview(id,{reviewTaskId:h.taskId,reviewAttempt:h.attempt,reportSha256:h.outcome.reportSha256,title:title.value,severity:severity.value,description:description.value});if(disposed||gen!==epoch)return;await load();emit('archived')}catch(e){if(!disposed&&gen===epoch)error.value='正式归档未完成：'+(e as Error).message}finally{busy.value=false}}
watch(()=>[props.groupId,props.revision],()=>{epoch++;clearTimeout(timer);value.value=null;title.value='';description.value='';ack.value=false;retryId='';void load()},{immediate:true});onBeforeUnmount(()=>{disposed=true;epoch++;clearTimeout(timer)});
</script>
<template>
 <section class="review-detail" aria-label="候选复核与归档详情"><header><h3>复核组 #{{groupId}}</h3><Button size="sm" variant="ghost" :disabled="loading" @click="load">刷新复核结论</Button></header>
 <p v-if="error" role="alert" class="review-error">{{error}}</p><p v-if="loading&&!value" role="status">正在读取冻结证据与复核结论…</p>
 <template v-if="value"><p>独立复核仅检查冻结源码与已保存证据。<strong>SDK“可报告”不等于已运行 PoC 或已复现。</strong> 费用按冻结单价与实际 Token 估算，缺少必要单价或用量时费用未知；详情见任务费用，不使用原扫描的累计预算。</p>
 <dl><div><dt>冻结源码</dt><dd><code>{{value.input.sourceContentHash}}</code></dd></div><div><dt>输入 SHA-256</dt><dd><code>{{value.inputSha256}}</code></dd></div><div><dt>分组依据</dt><dd>{{value.input.grouping==='exact'?'精确重复；未做语义猜测':value.input.groupingReason}}</dd></div></dl>
 <p>精确重复关联会保留各自来源；新增关联不代表已再次调用模型复核。</p><details><summary>原执行与候选证据关联（{{value.sources.length}} 份冻结输入）</summary><ul><li v-for="(source,i) in value.sources" :key="i"><RouterLink :to="'/scans/'+source.execution.taskId+'?attempt='+source.execution.attempt+'#interim-findings'">原任务 #{{source.execution.taskId}} · 第 {{source.execution.attempt}} 次</RouterLink><ul><li v-for="m in source.members" :key="m.candidate.id+':'+m.candidate.artifact">{{m.candidate.title}}<br/><code>候选 {{m.candidate.id}}<br/>证据 {{m.candidate.artifact}}</code></li></ul></li></ul></details>
 <div class="review-history"><table aria-label="候选独立复核历史"><thead><tr><th>独立执行</th><th>状态</th><th>SDK 结论</th><th>费用</th></tr></thead><tbody><tr v-for="h in value.history" :key="h.taskId"><td><RouterLink :to="'/scans/'+h.taskId">#{{h.taskId}} / {{h.attempt||'等待领取'}}</RouterLink></td><td><StatusBadge :status="h.status"/></td><td>{{h.outcome?(h.error&&h.report?'原生标签：':'')+dispositionLabels[h.outcome.disposition]:'尚无复核结论'}}<small v-if="h.outcome">{{h.error&&h.report?'未作为有效复核结论':'源码复核 · 未复现'}}</small><p v-if="h.error" class="review-error">{{h.error}}</p><details v-if="h.report&&h.taskId!==latest?.taskId"><summary>历史报告原文</summary><pre>{{h.report}}</pre></details></td><td>未知</td></tr></tbody></table></div>
 <p v-if="latest?.error&&latest.report" role="alert" class="review-error">复核输出未通过完整性检查。原始报告和 SDK 标签保留供诊断，当前候选仍待核查。</p>
 <template v-if="latest?.outcome"><p>报告 SHA-256：<code>{{latest.outcome.reportSha256}}</code></p><details open><summary>SDK 复核报告原文</summary><pre aria-label="候选复核报告原文">{{latest.report}}</pre></details></template>
 <section v-if="value.sourceCheck" aria-label="复核源码引用校验"><h4>源码引用校验</h4><p role="status"><strong>{{value.sourceCheck.state==='checked'?'引用位置已核对':'归档已阻止'}}</strong> · {{value.sourceCheck.reason}}</p><ul v-if="value.sourceCheck.state!=='checked'"><li v-for="(r,i) in value.sourceCheck.references.filter(r=>r.state!=='observed')" :key="i"><code>{{r.path}}:{{r.startLine}}-{{r.endLine}}</code> · {{r.reason}}</li></ul><p>只核对冻结版本、文件与行号，不证明模型解释、漏洞可利用性或运行时复现。</p></section>
 <p v-if="value.archive" role="status" class="archive-state">已正式归档：SDK 可报告 · 未复现。<RouterLink :to="{name:'scan-detail',params:{id:value.archive.execution.taskId},query:{finding:value.findingId}}">查看正式漏洞与证据图谱</RouterLink></p>
 <form v-else-if="canArchive&&canOperate" class="archive-form" aria-label="候选正式归档" @submit.prevent="archive"><h4>正式归档</h4><p>这是独立复核的归档记录，保留原扫描的失败或超时状态，不改写 SDK 原始扫描报告。严重度沿用模型初评，可在此调整。</p><label>归档标题<Input v-model="title" aria-label="归档标题" maxlength="2048" required/></label><label>归档严重度<Select v-model="severity" :options="options" aria-label="归档严重度"/></label><label class="full">归档说明（留空使用复核报告）<textarea v-model="description" aria-label="归档说明" rows="3" maxlength="65536"/></label><Button type="submit" size="sm" :loading="busy" :disabled="busy||!title.trim()">归档为可报告漏洞</Button></form>
 <p v-else-if="!active&&!value.archive">当前未满足归档条件：需要成功、可报告且源码引用校验通过。失败、待进一步核查、建议抑制和不适用均不会转成正式漏洞。</p>
 <div v-if="canOperate&&!active&&!value.archive" class="retry-review"><label><input v-model="ack" type="checkbox" :disabled="busy"/>重新复核会再次调用模型，费用未知；复用原冻结证据，不重新扫描。</label><Button size="sm" variant="outline" :disabled="!ack||busy" :loading="busy" @click="retry">重新发起独立复核</Button></div>
 </template></section>
</template>
<style scoped>
.review-detail{border-block:1px solid var(--border-default);padding-block:var(--space-3);margin-block:var(--space-3);min-width:0;font-size:var(--font-size-sm)}header{display:flex;justify-content:space-between;align-items:center;gap:var(--space-2);flex-wrap:wrap}h3,h4{font-size:var(--font-size-sm);font-weight:var(--font-weight-medium);margin:0}p{color:var(--text-secondary);line-height:var(--line-height-body);margin-block:var(--space-2);overflow-wrap:anywhere}strong{color:var(--text-primary);font-weight:var(--font-weight-medium)}dl>div{display:grid;grid-template-columns:120px minmax(0,1fr);gap:var(--space-2);padding-block:var(--space-1)}dt{color:var(--text-secondary)}dd{margin:0;overflow-wrap:anywhere}code,pre{font-family:var(--font-mono);font-size:var(--font-size-xs);overflow-wrap:anywhere;white-space:pre-wrap}pre{padding:var(--space-2);background:var(--surface-secondary);max-height:400px;overflow:auto}summary{cursor:pointer;margin-block:var(--space-2)}a{color:var(--accent-primary)}li{overflow-wrap:anywhere;margin-block:var(--space-1)}.review-history{overflow:auto;margin-block:var(--space-3)}table{width:100%;border-collapse:collapse;text-align:start;min-width:430px}th,td{padding:var(--space-2);border-bottom:1px solid var(--border-subtle);vertical-align:top}th{font-weight:var(--font-weight-medium);color:var(--text-secondary)}td small{display:block;color:var(--text-secondary);font-size:var(--font-size-xs)}.review-error{color:var(--state-danger)}.archive-state{color:var(--text-primary)}.archive-form{display:grid;grid-template-columns:minmax(0,1fr) 200px;gap:var(--space-2);border-top:1px solid var(--border-default);padding-top:var(--space-3);margin-top:var(--space-3)}.archive-form>button{justify-self:start}.archive-form>h4,.archive-form>p,.full{grid-column:1/-1}label{display:flex;flex-direction:column;gap:var(--space-1)}textarea{border:1px solid var(--border-default);border-radius:var(--radius-sm);padding:var(--space-2);background:var(--surface-primary);resize:vertical;color:var(--text-primary);width:100%;box-sizing:border-box}.retry-review{border-top:1px solid var(--border-default);padding-top:var(--space-3);margin-top:var(--space-3)}.retry-review label{display:flex;flex-direction:row;align-items:flex-start;gap:var(--space-2);margin-bottom:var(--space-2)}@media(max-width:640px){dl>div,.archive-form{grid-template-columns:minmax(0,1fr)}.archive-form>*{grid-column:1}}
</style>
